/**
 * Programmatic SEO hub-page seed data for BloomYourGut.
 *
 * Source of truth for three route families:
 *   /conditions/[slug]  — gut conditions (SIBO, IBS, leaky gut, ...)
 *   /symptoms/[slug]    — symptoms (bloating, brain fog, constipation, ...)
 *   /foods/[slug]       — foods, supplements & compounds (bone broth, berberine, ...)
 *
 * Each entry is structured data that the route templates expand into a full
 * MedicalWebPage: an overview, an FAQ (with schema.org markup), affiliate
 * product recommendations, matching articles from Supabase, and crosslinks.
 *
 * The AI-generated overview is produced from this structured data (see
 * `src/lib/ai/hub-content.ts` for the enrichment path that can regenerate the
 * `overview` HTML with Claude). Templated rendering keeps `next build` green
 * without any network calls.
 */

export type HubCategory = 'conditions' | 'symptoms' | 'foods'

export interface HubFaq {
  question: string
  answer: string
}

/** Compact authoring shape used in the data arrays below. */
export interface HubSeed {
  slug: string
  name: string
  /** Synonyms / alternate names — feed keywords and "also known as". */
  aka?: string[]
  /** One- to two-sentence lede. */
  summary: string
  /** 4-6 substantive bullets woven into the overview and FAQ. */
  keyPoints: string[]
  /** Custom FAQ; auto-templated from keyPoints when omitted. */
  faq?: HubFaq[]
  /** Explicit crosslinks as "category/slug" or bare slug (same category). */
  related?: string[]
  /** Maps to affiliate_products.category for product recs. */
  affiliateCategory?: string
  /** Categories/tags matched against the articles table. */
  articleCategories?: string[]
  /** Topical tags used for automatic related-page discovery. */
  tags?: string[]
}

/** Fully-expanded hub page consumed by the route templates. */
export interface HubPage {
  category: HubCategory
  slug: string
  href: string
  name: string
  title: string
  aka: string[]
  summary: string
  keyPoints: string[]
  faq: HubFaq[]
  related: string[]
  affiliateCategory: string | null
  articleCategories: string[]
  tags: string[]
}

const SITE = 'https://bloomyourgut.com'

/** Compact authoring helper — keeps the data arrays readable. */
function seed(
  slug: string,
  name: string,
  summary: string,
  keyPoints: string[],
  opts: Partial<Omit<HubSeed, 'slug' | 'name' | 'summary' | 'keyPoints'>> = {}
): HubSeed {
  return { slug, name, summary, keyPoints, ...opts }
}

