// ============================================================
// Builder + public API
// ============================================================

const CATEGORY_TITLE: Record<HubCategory, (name: string) => string> = {
  conditions: (n) => `${n}: Symptoms, Causes & Evidence-Based Treatment`,
  symptoms: (n) => `${n}: Gut-Health Causes, Relief & When to Worry`,
  foods: (n) => `${n} for Gut Health: Benefits, Evidence & How to Use`,
}

const CATEGORY_NOUN: Record<HubCategory, string> = {
  conditions: 'condition',
  symptoms: 'symptom',
  foods: 'food',
}

/** Build a default FAQ from the entry's key points when none is authored. */
function defaultFaq(category: HubCategory, s: HubSeed): HubFaq[] {
  const noun = CATEGORY_NOUN[category]
  const faqs: HubFaq[] = [
    {
      question: `What is ${s.name}?`,
      answer: `${s.summary} ${s.keyPoints[0] ?? ''}`.trim(),
    },
  ]
  if (category === 'foods') {
    faqs.push(
      { question: `How does ${s.name} support gut health?`, answer: s.keyPoints.slice(0, 2).join(' ') },
      { question: `How should I use ${s.name}?`, answer: s.keyPoints[2] ?? `${s.name} can be incorporated gradually as part of a gut-supportive routine; start with small amounts and monitor your response.` },
      { question: `Are there any cautions with ${s.name}?`, answer: s.keyPoints[3] ?? `Introduce ${s.name} slowly, especially if you have a sensitive gut, and consult a healthcare provider if you have an underlying condition.` }
    )
  } else {
    faqs.push(
      { question: `What causes ${s.name}?`, answer: s.keyPoints.slice(0, 2).join(' ') },
      { question: `How is ${s.name} managed?`, answer: s.keyPoints[2] ?? `Managing this ${noun} starts with identifying root causes and supporting the gut with targeted diet and lifestyle changes.` },
      { question: `When should I see a doctor about ${s.name}?`, answer: s.keyPoints[3] ?? `See a healthcare provider if symptoms are severe, persistent, or accompanied by red flags such as bleeding, unintended weight loss, or fever.` }
    )
  }
  return faqs
}

function buildHubPage(category: HubCategory, s: HubSeed): HubPage {
  return {
    category,
    slug: s.slug,
    href: `/${category}/${s.slug}`,
    name: s.name,
    title: CATEGORY_TITLE[category](s.name),
    aka: s.aka ?? [],
    summary: s.summary,
    keyPoints: s.keyPoints,
    faq: s.faq ?? defaultFaq(category, s),
    related: (s.related ?? []).map((r) => (r.includes('/') ? r : `${category}/${r}`)),
    affiliateCategory: s.affiliateCategory ?? null,
    articleCategories: s.articleCategories ?? [],
    tags: s.tags ?? [],
  }
}

/** All hub pages across the three families. */
export const HUB_PAGES: HubPage[] = [
  ...CONDITIONS.map((s) => buildHubPage('conditions', s)),
  ...SYMPTOMS.map((s) => buildHubPage('symptoms', s)),
  ...FOODS.map((s) => buildHubPage('foods', s)),
]

const BY_KEY: Map<string, HubPage> = new Map(
  HUB_PAGES.map((p) => [`${p.category}/${p.slug}`, p])
)

/** Pages within a single category. */
export function getHubPagesByCategory(category: HubCategory): HubPage[] {
  return HUB_PAGES.filter((p) => p.category === category)
}

/** Look up one page by category + slug. */
export function getHubPage(category: HubCategory, slug: string): HubPage | undefined {
  return BY_KEY.get(`${category}/${slug}`)
}

/** Resolve a "category/slug" or bare reference to a full page. */
export function resolveHubRef(ref: string, fallbackCategory: HubCategory): HubPage | undefined {
  const key = ref.includes('/') ? ref : `${fallbackCategory}/${ref}`
  return BY_KEY.get(key)
}

/**
 * Related pages for crosslinking: explicit `related` refs first, then
 * topically-similar pages discovered via shared tags, up to `limit`.
 */
export function getRelatedHubPages(page: HubPage, limit = 6): HubPage[] {
  const out: HubPage[] = []
  const seen = new Set<string>([`${page.category}/${page.slug}`])

  for (const ref of page.related) {
    const target = resolveHubRef(ref, page.category)
    if (target && !seen.has(`${target.category}/${target.slug}`)) {
      out.push(target)
      seen.add(`${target.category}/${target.slug}`)
    }
  }

  if (out.length < limit && page.tags.length) {
    const tagSet = new Set(page.tags)
    const scored = HUB_PAGES.filter((p) => !seen.has(`${p.category}/${p.slug}`))
      .map((p) => ({ p, score: p.tags.filter((t) => tagSet.has(t)).length }))
      .filter((x) => x.score > 0)
      .sort((a, b) => b.score - a.score)
    for (const { p } of scored) {
      if (out.length >= limit) break
      out.push(p)
      seen.add(`${p.category}/${p.slug}`)
    }
  }

  return out.slice(0, limit)
}

export const HUB_CATEGORIES: HubCategory[] = ['conditions', 'symptoms', 'foods']

/** Absolute canonical URL for a hub page. */
export function hubPageUrl(page: HubPage): string {
  return `${SITE}${page.href}`
}
